/* The "plain" base map style (muted grey ground, light green open land with park / forest-preserve names, outlined buildings, dark street names, today's house numbers from zoom 18; no city names or boundary lines).
   Shared by the viewer (docs/index.html) and the picture-tile renderer (scripts/basemap_raster_job.html) so the two cannot drift apart. Needs protomaps-leaflet loaded first (window.protomapsL).
   plainStyle(flavorUrl) -> {paintRules, labelRules, backgroundColor} for protomapsL.leafletLayer(). */
window.plainStyle=async function(flavorUrl){const fl=await (await fetch(flavorUrl)).json();
 const LAND={'#d3dfca':['pitch','garden','recreation_ground','dog_park','playground','common','village_green','park'],'#cfdcc6':['meadow','grassland','grass'],'#dfe3d2':['farmland'],'#cbd9d3':['wetland'],'#cedbc5':['golf_course','cemetery','allotments','nature_reserve']};
 // (no city/county/state outlines: the 'boundaries' layer is dropped; no city names: the 'places' labels are dropped)
 const paint=protomapsL.paintRules(fl).filter(r=>r.dataLayer!=='buildings'&&r.dataLayer!=='boundaries');let li=-1;paint.forEach((r,i)=>{if(r.dataLayer==='landuse'||r.dataLayer==='landcover'||r.dataLayer==='natural')li=i});
 paint.splice(li+1,0,...Object.entries(LAND).map(([fill,kinds])=>({dataLayer:'landuse',symbolizer:new protomapsL.PolygonSymbolizer({fill}),filter:(z,f)=>kinds.includes(f.props.kind)})));   // land kinds the library has no colour for (pitches, gardens, meadows, wetlands...)
 paint.push({dataLayer:'buildings',symbolizer:new protomapsL.PolygonSymbolizer({fill:fl.buildings,stroke:'#9c9c9c',width:0.9})});
 const lab=protomapsL.labelRules(fl).filter(r=>r.dataLayer!=='places');lab.push({dataLayer:'pois',symbolizer:new protomapsL.CenteredTextSymbolizer({labelProps:['name'],fill:'#4e6745',stroke:'#e6ece1',width:1.5,font:(z)=>'italic 500 '+(z<14?12:11)+'px sans-serif'}),filter:(z,f)=>['park','nature_reserve','forest','wood','garden','golf_course','dog_park','recreation_ground','cemetery','zoo','playground'].includes(f.props.kind)&&!!f.props.name&&z>=Math.max(15,f.props.min_zoom||0)});   // park, forest preserve and other open-space names (point labels; each has its own minimum zoom, and none below zoom 15: the viewer shows permit dots from zoom 15, and zoomed out the names would clutter the community-area counts)
 lab.push({dataLayer:'buildings',symbolizer:new protomapsL.CenteredTextSymbolizer({labelProps:['addr_housenumber'],fill:'#4f4f4f',stroke:'#e4e4e4',width:1.5,font:()=>'500 11px sans-serif'}),filter:(z,f)=>f.props.kind==='address',minzoom:18});   // today's house numbers
 return {paintRules:paint,labelRules:lab,backgroundColor:fl.background}};
